use super::{error, SystemResult, SystemScope};
use shellfox_protocol::ErrorCode;
use std::{
    path::{Path, PathBuf},
    sync::Arc,
};

pub const POSIX_OWNER: &str = "Shellfox/linux-v1";

#[derive(Clone, Debug)]
pub struct ManagedFile {
    pub path: PathBuf,
    pub bytes: Vec<u8>,
    pub executable: bool,
}
#[derive(Clone, Debug)]
pub struct CliInstallPlan {
    pub directory: PathBuf,
    pub files: Vec<ManagedFile>,
    /// Exact ownership receipt generated by the configured package producer.
    pub marker: PathBuf,
    pub package_managed: bool,
}
/// Installer configuration for a local user-initiated NewSession launch. This
/// is not Georgia's private desktop_launch request or its dedup/window router.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum DesktopLaunchDisposition {
    #[default]
    ExistingWindow,
    NewWindow,
}
#[derive(Clone, Debug)]
pub struct DesktopLaunch {
    pub executable: PathBuf,
    /// Trusted fixed prefix only. No request/renderer text is accepted here.
    pub prefix_arguments: Vec<String>,
    /// The configured executable really supports --new-session --cwd.
    pub new_session_contract: bool,
    /// Explicit desktop-program argv disposition, used by Windows Explorer.
    /// CLI-start menus use their separate default invocation contract below.
    /// Never infer this value from programmatic create.
    pub disposition: DesktopLaunchDisposition,
    /// Linux file menus invoke this validated CLI's local start <path> contract.
    /// CLI owns aliases and invoking-cwd resolution; menu selections are already
    /// absolute. The installer never generates or pins a request dedup ID.
    pub cli_start: Option<PathBuf>,
}

/// Only host composition constructs this provider after validating the package
/// resources and stable install layout. It is deliberately not deserializable.
/// Never implement it with current_exe(), an acceptance EXE, or runtime self-hash.
pub trait SystemInstallResources: Send + Sync {
    fn cli_plan(&self, scope: SystemScope) -> SystemResult<CliInstallPlan>;
    fn desktop_launch(&self) -> SystemResult<DesktopLaunch>;
    fn validate_current(&self) -> SystemResult<()>;
}

/// Existing stable-install root gate, also used before accepting inventory-only
/// resources. This does not authenticate a package or authorize any mutation.
pub fn validate_stable_package_root(package_root: &Path) -> SystemResult<()> {
    super::validation::absolute_path(package_root)?;
    let temp = std::env::temp_dir();
    let in_temp = package_root.starts_with(&temp)
        || std::fs::canonicalize(package_root)
            .ok()
            .zip(std::fs::canonicalize(&temp).ok())
            .is_some_and(|(root, temp)| root.starts_with(temp));
    if in_temp {
        return Err(error(
            ErrorCode::Unsupported,
            "Temporary acceptance resources cannot be installed.",
        ));
    }
    if package_root.components().any(|part| matches!(part, std::path::Component::Normal(name) if name.to_str().is_some_and(|name|["tmp","temp","target"].iter().any(|part|name.eq_ignore_ascii_case(part))))) {
        return Err(error(ErrorCode::Unsupported, "Temporary acceptance/build paths cannot provide installation resources."));
    }
    Ok(())
}

pub struct ConfiguredSystemResources {
    user: CliInstallPlan,
    system: Option<CliInstallPlan>,
    desktop: Option<DesktopLaunch>,
    package_root: PathBuf,
    _validated_resource_lease: Arc<dyn Send + Sync>,
}
impl ConfiguredSystemResources {
    /// Caller supplies an already validated package lease. Structural checks
    /// here are not publisher authentication and cannot manufacture that lease.
    pub fn from_validated_package(
        package_root: PathBuf,
        user: CliInstallPlan,
        system: Option<CliInstallPlan>,
        desktop: Option<DesktopLaunch>,
        lease: Arc<dyn Send + Sync>,
    ) -> SystemResult<Self> {
        validate_stable_package_root(&package_root)?;
        Self::checked(package_root, user, system, desktop, lease)
    }
    fn checked(
        package_root: PathBuf,
        user: CliInstallPlan,
        system: Option<CliInstallPlan>,
        desktop: Option<DesktopLaunch>,
        lease: Arc<dyn Send + Sync>,
    ) -> SystemResult<Self> {
        validate_plan(&user)?;
        if let Some(plan) = &system {
            validate_plan(plan)?;
        }
        if let Some(launch) = &desktop {
            validate_desktop_prefix(launch)?;
            if !launch.executable.starts_with(&package_root) {
                return Err(error(
                    ErrorCode::Validation,
                    "Invalid stable desktop launch resources.",
                ));
            }
        }
        Ok(Self {
            user,
            system,
            desktop,
            package_root,
            _validated_resource_lease: lease,
        })
    }
    #[cfg(test)]
    pub(super) fn fixture(
        root: PathBuf,
        user: CliInstallPlan,
        desktop: Option<DesktopLaunch>,
    ) -> SystemResult<Self> {
        Self::checked(root, user, None, desktop, Arc::new(()))
    }
}
impl SystemInstallResources for ConfiguredSystemResources {
    fn cli_plan(&self, scope: SystemScope) -> SystemResult<CliInstallPlan> {
        match scope {
            SystemScope::User => Ok(self.user.clone()),
            SystemScope::System => self.system.clone().ok_or_else(|| {
                error(
                    ErrorCode::Unsupported,
                    "No configured system CLI installation layout.",
                )
            }),
        }
    }
    fn desktop_launch(&self) -> SystemResult<DesktopLaunch> {
        self.desktop.clone().ok_or_else(|| {
            error(
                ErrorCode::Unsupported,
                "Stable packaged desktop launch resources are unavailable.",
            )
        })
    }
    fn validate_current(&self) -> SystemResult<()> {
        if !self.package_root.is_dir() {
            return Err(error(
                ErrorCode::NativeUnavailable,
                "Configured package installation is unavailable.",
            ));
        }
        if let Some(launch) = &self.desktop {
            if !launch.executable.is_file() {
                return Err(error(
                    ErrorCode::NativeUnavailable,
                    "Configured packaged executable is unavailable.",
                ));
            }
        }
        Ok(())
    }
}
pub(super) fn validate_desktop_prefix(launch: &DesktopLaunch) -> SystemResult<()> {
    super::validation::absolute_path(&launch.executable)?;
    if launch.prefix_arguments.len() > 16
        || launch.prefix_arguments.iter().any(|arg| {
            let flag = arg.split('=').next().unwrap_or_default();
            arg.len() > 32767
                || arg.chars().any(char::is_control)
                || matches!(
                    flag,
                    "--new-session"
                        | "--cwd"
                        | "--new-window"
                        | "--request-id"
                        | "--host"
                        | "--open-session"
                )
        })
    {
        return Err(error(ErrorCode::Validation,"Desktop prefixes may not override local intent, disposition, cwd or per-invocation dedup identity."));
    }
    Ok(())
}

pub(super) fn validate_plan(plan: &CliInstallPlan) -> SystemResult<()> {
    super::validation::absolute_path(&plan.directory)?;
    if plan.files.is_empty()
        || plan.files.len() > 16
        || plan.marker.parent() != Some(plan.directory.as_path())
    {
        return Err(error(ErrorCode::Validation, "Invalid CLI resource plan."));
    }
    let mut paths = std::collections::BTreeSet::new();
    for file in &plan.files {
        if file.path.parent() != Some(plan.directory.as_path())
            || file.bytes.len() > 1024 * 1024
            || !paths.insert(&file.path)
        {
            return Err(error(
                ErrorCode::Validation,
                "CLI resource escapes its configured directory or exceeds bounds.",
            ));
        }
    }
    if !plan
        .files
        .iter()
        .any(|file| file.path == plan.marker && owns_file(&file.bytes))
    {
        return Err(error(
            ErrorCode::Validation,
            "CLI ownership receipt is missing or invalid.",
        ));
    }
    Ok(())
}
/// Shellfox-written POSIX files carry this owner line, as in 0.9.
pub(super) fn owns_file(bytes: &[u8]) -> bool {
    std::str::from_utf8(bytes).is_ok_and(|text| {
        text.lines()
            .any(|line| line.trim_end_matches('\r') == format!("# {POSIX_OWNER}"))
    })
}
